const STORAGE_KEY = "boshiamy-practice-stats-v1";
const AUTO_NEXT_KEY = "boshiamy-auto-next-v2";

function loadAutoNext(fallback: boolean): boolean {
  try {
    const raw = localStorage.getItem(AUTO_NEXT_KEY);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* ignore quota / private mode */
  }
  return fallback;
}


type SavedStats = {
  ok: number;
  tried: number;
  streak: number;
  missChars: Record<string, number>;
  missRoots: Record<string, number>;
};

function emptyStats(): SavedStats {
  return { ok: 0, tried: 0, streak: 0, missChars: {}, missRoots: {} };
}

function loadStats(): SavedStats {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return emptyStats();
    return sanitizeStats(JSON.parse(raw) as unknown);
  } catch {
    return emptyStats();
  }
}

